arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_f4f017a300a04e1b84d8e5c943f35e4d.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* Step Indicator Bar *@
<div class="step-indicator">
    @for (int i = 0; i < _stepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < _currentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@_stepNames[stepIndex]</div>
        </div>
        @if (i < _stepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < _currentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger mt-3">@_errorMessage</div>
}

@* Step Content *@
<div class="step-content mt-4">
    @switch (_currentStep)
    {
        case 0:
            @RenderPersonalInfo()
            break;
        case 1:
            @RenderWorkHistory()
            break;
        case 2:
            @RenderReferences()
            break;
        case 3:
            @RenderCoverLetter()
            break;
        case 4:
            @RenderReviewSubmit()
            break;
    }
</div>

@* --- Step Renderers --- *@

@code {
    private RenderFragment RenderPersonalInfo() => __builder =>
    {
        <h2>Personal Information</h2>
        <div class="form-group mb-3">
            <label for="fullName">Full Name *</label>
            <input id="fullName" class="form-control" @bind="_fullName" placeholder="Enter your full name" />
        </div>
        <div class="form-group mb-3">
            <label for="email">Email *</label>
            <input id="email" type="email" class="form-control" @bind="_email" placeholder="Enter your email" />
            @if (!string.IsNullOrEmpty(_emailValidationMessage))
            {
                <small class="text-danger">@_emailValidationMessage</small>
            }
        </div>
        <div class="form-group mb-3">
            <label for="phone">Phone *</label>
