                        </div>
                    </div>
                </div>
                <div class="form-group mb-2">
                    <label>Description</label>
                    <textarea class="form-control" rows="3" value="@entry.Description" @onchange="(e) => UpdateWorkEntry(index, entry with { Description = e.Value?.ToString() ?? string.Empty })"></textarea>
                </div>
